INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (23001, 0, 20001, 0, 20, 320, 2, 10, "", "", 0);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (24001, 1, 40011, 0, 1, 321, 2, 1, "もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n", "リリ", 125801);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (24001, 1, 40011, 0, 1, 322, 2, 2, "初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます", "クリア", 126001);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (24001, 1, 40011, 0, 1, 323, 2, 3, "んーと。\nこれ、あげる。\nはい", "プレシア", 126101);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (24001, 2, 40011, 0, 1, 324, 2, 4, "あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します", "リリ", 125801);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (24001, 2, 40011, 0, 1, 325, 2, 5, "こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです", "クリア", 126001);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES (24001, 2, 40011, 0, 1, 326, 2, 6, "お兄。\nきてくれて、うれしい", "プレシア", 126101);
